<?php
namespace App\Controllers\Admin;use App\Support\App;use App\Services\Provider\CeirGoProvider;
final class ProductController{
 public function save():never{App::requireAdmin();$in=App::input();$db=App::db();$id=(int)($in['id']??0);$data=[trim($in['name']??''),trim($in['code']??''),$in['description']??'',in_array($in['provider_type']??'manual',['manual','ceirgo'],true)?$in['provider_type']:'manual',$in['provider_service_id']??null,$in['provider_service_code']??null,(float)($in['provider_cost']??0),$in['whatsapp_group_id']??null,!empty($in['ceir_check_enabled'])?1:0,!empty($in['auto_refund'])?1:0,!empty($in['is_active'])?1:0,$in['processing_time']??null,(int)($in['sort_order']??0)];if(!$data[0]||!$data[1])App::json(['ok'=>false,'message'=>'Nama/code wajib'],422);if($id){$data[]=$id;$db->prepare('UPDATE products SET name=?,code=?,description=?,provider_type=?,provider_service_id=?,provider_service_code=?,provider_cost=?,whatsapp_group_id=?,ceir_check_enabled=?,auto_refund=?,is_active=?,processing_time=?,sort_order=? WHERE id=?')->execute($data);}else{$db->prepare('INSERT INTO products(name,code,description,provider_type,provider_service_id,provider_service_code,provider_cost,whatsapp_group_id,ceir_check_enabled,auto_refund,is_active,processing_time,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)$db->lastInsertId();}foreach((array)($in['prices']??[]) as $level=>$price){$q=$db->prepare('SELECT id FROM user_levels WHERE code=?');$q->execute([$level]);if($lid=$q->fetchColumn())$db->prepare('INSERT INTO product_prices(product_id,level_id,price) VALUES(?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price)')->execute([$id,$lid,(float)$price]);}App::json(['ok'=>true,'id'=>$id]);}
 public function importCeirGo():never{App::requireAdmin();try{$r=(new CeirGoProvider())->services();$items=$r['data']['page']['items']??[];$db=App::db();foreach($items as $s)$db->prepare('INSERT INTO provider_services(provider,provider_service_id,code,name,description,is_active,raw_json) VALUES("ceirgo",?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),description=VALUES(description),is_active=VALUES(is_active),raw_json=VALUES(raw_json),updated_at=NOW()')->execute([(string)$s['id'],$s['code'],$s['name'],$s['description']??null,!empty($s['is_active'])?1:0,json_encode($s)]);App::json(['ok'=>true,'imported'=>count($items)]);}catch(\Throwable $e){App::json(['ok'=>false,'message'=>$e->getMessage()],502);}}
}
